/// <reference types="vite/client" />

interface ImportMetaEnv {
  /** Куда житель пишет, чтобы удалить свои контакты или уточнить судьбу заявки
   *  (PRD §9.2.4). Значение задаёт владелец кампании при сборке. */
  readonly VITE_CAMPAIGN_CONTACT_URL?: string
  /** Ключ Яндекс JS API v3. Берутся только виджет выбора точки и тайлы; геокодер
   *  не вызывается никогда (ADR-0004). Ключа нет — карта не грузится, и выбор точки
   *  идёт кнопкой «моё местоположение» и полями широты и долготы (PRD §8.2). */
  readonly VITE_YANDEX_MAPS_API_KEY?: string
}
